public long countInversions(int[] nums) {
    int[] buffer = new int[nums.length];
    return mergeSort(nums, buffer, 0, nums.length - 1);
}

private long mergeSort(int[] nums, int[] buffer, int lo, int hi) {
    if (lo >= hi) return 0;
    int mid = lo + (hi - lo) / 2;
    long count = mergeSort(nums, buffer, lo, mid)
               + mergeSort(nums, buffer, mid + 1, hi);
    count += merge(nums, buffer, lo, mid, hi);
    return count;
}

private long merge(int[] nums, int[] buffer, int lo, int mid, int hi) {
    int i = lo, j = mid + 1, k = lo;
    long count = 0;
    while (i <= mid && j <= hi) {
        if (nums[i] <= nums[j]) {
            buffer[k++] = nums[i++];          // no inversion (<= handles ties)
        } else {
            buffer[k++] = nums[j++];
            count += (mid - i + 1);           // all remaining left elements > nums[j]
        }
    }
    while (i <= mid) buffer[k++] = nums[i++];
    while (j <= hi) buffer[k++] = nums[j++];
    System.arraycopy(buffer, lo, nums, lo, hi - lo + 1);
    return count;
}

